    "faqs": [
      {
        "q": "What is asymmetric encryption in PKI?",
        "a": "Asymmetric encryption uses a public key to encrypt data and a mathematically related private key to decrypt it, ensuring security without pre-sharing keys."
      },
      {
        "q": "What is the difference between CRL and OCSP?",
        "a": "CRL is a complete downloadable list of revoked certificates, whereas OCSP is an active API query to check the revocation status of a single certificate."
      }
    ],
